 */

scwin.onpageload = function () {

};

/**
 * @method
 * @name checkMaxLength
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.checkMaxLength = function (obj, size, lbl) {
    const overLen = eval(scwin.getStringSize(scwin.getObjectValue(obj)) - size);

    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ "
            + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }

    return true;
};

/**
 * @method
 * @name setFromToDate
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.setFromToDate = function (pTp, pObjFrom, pObjTo) {
    // 1주일^1,1개월^2,3개월^3,6개월^4,1년^5,2년^6
    let vFrom = "";
    let vTo = pObjTo.getValue();

    if (vTo === '') {	// 값이 없으면 현재일 기준으로 계산
        vTo = $c.date.getServerDateTime("yyyymmdd");
    }

    if (pTp.toString() === "1") {
        vFrom = $c.date.addDate(vTo, -7); 	    // 일주일전		
    } else if (pTp.toString() === "2") {		// 1개월전
        vFrom = $c.date.addMonth(vTo, -1);
    } else if (pTp.toString() === "3") {		// 3개월전
        vFrom = $c.date.addMonth(vTo, -3);
    } else if (pTp.toString() === "4") {		// 6개월전
        vFrom = $c.date.addMonth(vTo, -6);
    } else if (pTp.toString() === "5") {	    // 1년전
        vFrom = $c.date.addYear(vTo, -1);
    } else if (pTp.toString() === "6") {	    // 2년전
        vFrom = $c.date.addYear(vTo, -2);
    }

    pObjFrom.setValue(vFrom);
    pObjTo.setValue(vTo);
};
